import assert from "node:assert/strict";
import { test } from "node:test";
import { decide } from "../screens/access.ts";
import { schema } from "../app/loans/page.schema.ts";

test("loans-list is refused to someone signed in without loans.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: [] }), "refused");
});

test("loans-list sends someone signed out to sign in", () => {
  assert.equal(decide(schema.permission, { signedIn: false, permissions: [] }), "sign-in");
});

test("loans-list opens to someone who holds loans.read", () => {
  assert.equal(decide(schema.permission, { signedIn: true, permissions: ["loans.read"] }), "allowed");
});
